#!/usr/bin/env node
/*
 * GASTO DIARIO DO GOOGLE ADS + CUSTO POR PERIODO - Studio Realcar
 *
 * 1) Um script agendado DENTRO do Google Ads manda todo dia o gasto de cada
 *    campanha em cada dia. O sistema lanca no Financeiro uma saida paga por dia,
 *    na data certa (conta principal), sem duplicar e corrigindo se o Google mudar.
 *    Tela nova: Marketing > "Gasto Google Ads" (ligar campanhas, dia de inicio).
 * 2) Os blocos manuais antigos podem ser trocados pelo gasto de cada dia com o
 *    MESMO total por conta: o saldo nao muda. Os blocos ficam guardados como
 *    cancelados, com o motivo anotado.
 * 3) "Lancar custo" ganhou o campo "Ate": o valor e dividido pelos dias do periodo.
 *
 * Cria 1 tabela e 3 colunas (migracao automatica no deploy).
 * Pode rodar mais de uma vez; se algum trecho nao for encontrado, NADA e gravado.
 *
 * Uso: node gasto-google-ads-diario.mjs
 */
import fs from "node:fs";
import path from "node:path";

const DATA = {"novosArquivos":{"lib/gasto-google-ads.ts":"import { prisma } from \"@/lib/prisma\";\n\n/**\n * Gasto diario do Google Ads.\n *\n * Um script agendado DENTRO do Google Ads manda, todo dia, quanto cada\n * campanha gastou em cada um dos ultimos dias. Aqui o sistema:\n *  1) guarda o que chegou (GastoGoogleAdsDia), sem duplicar o mesmo dia;\n *  2) para cada campanha do sistema ligada a uma campanha do Google, lanca no\n *     Financeiro UMA saida paga por dia, na data certa, a partir do dia\n *     escolhido (\"gastoAutomaticoDesde\"). Se o Google corrigir um dia, o mesmo\n *     lancamento e atualizado (chave unica por campanha + dia).\n *\n * Os blocos manuais antigos (varios dias num lancamento so) podem ser\n * substituidos pelo gasto de cada dia SEM mudar o saldo: o mesmo total lancado\n * a mao e redistribuido pelos dias, na proporcao do que o Google mostra.\n */\n\nexport const ORIGEM_GASTO_AUTOMATICO = \"Google Ads (automático)\";\nexport const ORIGEM_GASTO_AJUSTE = \"Google Ads (ajuste dos blocos)\";\nconst FUSO = \"America/Sao_Paulo\";\nconst MAXIMO_LINHAS = 20000;\n\nexport type LinhaGastoRecebida = {\n  googleCampanhaId: string;\n  campanha: string;\n  data: string;\n  custo: number;\n};\n\n/* ------------------------------------------------------------------ datas */\n\nexport function diaValido(valor: unknown): valor is string {\n  if (typeof valor !== \"string\" || !/^\\d{4}-\\d{2}-\\d{2}$/.test(valor)) return false;\n  const [ano, mes, dia] = valor.split(\"-\").map(Number);\n  const data = new Date(Date.UTC(ano, mes - 1, dia));\n  return (\n    data.getUTCFullYear() === ano && data.getUTCMonth() === mes - 1 && data.getUTCDate() === dia\n  );\n}\n\nexport function somarDias(dia: string, quantidade: number): string {\n  const [ano, mes, d] = dia.split(\"-\").map(Number);\n  const data = new Date(Date.UTC(ano, mes - 1, d + quantidade));\n  return data.toISOString().slice(0, 10);\n}\n\n/** Dia de hoje (ou da data informada) no horario de Brasilia, \"2026-10-15\". */\nexport function diaDe(data: Date = new Date()): string {\n  return new Intl.DateTimeFormat(\"en-CA\", {\n    timeZone: FUSO,\n    year: \"numeric\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n  }).format(data);\n}\n\n/** Meio-dia do dia em Brasilia: o mesmo horario usado no \"Lancar custo\". */\nexport function dataDoDia(dia: string): Date {\n  return new Date(`${dia}T12:00:00-03:00`);\n}\n\nexport function diaFormatado(dia: string): string {\n  const [ano, mes, d] = dia.split(\"-\");\n  return `${d}/${mes}/${ano}`;\n}\n\nexport function diasEntre(inicio: string, fim: string): string[] {\n  const dias: string[] = [];\n  let atual = inicio;\n  while (atual <= fim && dias.length < 1000) {\n    dias.push(atual);\n    atual = somarDias(atual, 1);\n  }\n  return dias;\n}\n\n/**\n * Divide um total (em reais) em partes proporcionais aos pesos, em centavos,\n * de forma que a soma das partes seja EXATAMENTE o total. Sem pesos validos,\n * divide por igual.\n */\nexport function distribuirValor(total: number, pesos: number[]): number[] {\n  if (pesos.length === 0) return [];\n  const totalCentavos = Math.round(total * 100);\n  const somaPesos = pesos.reduce((soma, peso) => soma + Math.max(0, peso), 0);\n  const base = somaPesos > 0 ? pesos.map((peso) => Math.max(0, peso)) : pesos.map(() => 1);\n  const somaBase = somaPesos > 0 ? somaPesos : pesos.length;\n\n  const exatos = base.map((peso) => (totalCentavos * peso) / somaBase);\n  const partes = exatos.map((valor) => Math.floor(valor));\n  let sobra = totalCentavos - partes.reduce((soma, valor) => soma + valor, 0);\n\n  // Os centavos que sobraram vao para quem tinha a maior fracao.\n  const ordem = exatos\n    .map((valor, indice) => ({ indice, fracao: valor - Math.floor(valor) }))\n    .sort((a, b) => b.fracao - a.fracao || a.indice - b.indice);\n  for (let i = 0; sobra > 0 && i < ordem.length; i += 1, sobra -= 1) {\n    partes[ordem[i].indice] += 1;\n  }\n\n  return partes.map((centavos) => centavos / 100);\n}\n\n/* --------------------------------------------------------------- recebimento */\n\n/** Confere e limpa o que o script do Google Ads mandou. */\nexport function normalizarLinhasRecebidas(corpo: unknown): {\n  linhas: LinhaGastoRecebida[];\n  ignoradas: number;\n} {\n  const lista =\n    corpo && typeof corpo === \"object\" && Array.isArray((corpo as { linhas?: unknown }).linhas)\n      ? ((corpo as { linhas: unknown[] }).linhas)\n      : [];\n\n  const porChave = new Map<string, LinhaGastoRecebida>();\n  let ignoradas = 0;\n\n  for (const item of lista.slice(0, MAXIMO_LINHAS)) {\n    const linha = item as Record<string, unknown>;\n    const googleCampanhaId = String(linha?.googleCampanhaId ?? \"\").trim();\n    const campanha = String(linha?.campanha ?? \"\").trim().slice(0, 200);\n    const data = String(linha?.data ?? \"\").trim();\n    const custo = Number(linha?.custo);\n\n    if (!/^\\d{1,20}$/.test(googleCampanhaId) || !diaValido(data) || !Number.isFinite(custo) || custo < 0) {\n      ignoradas += 1;\n      continue;\n    }\n\n    // Se o mesmo dia vier repetido, soma (pode acontecer se o Google separar linhas).\n    const chave = `${googleCampanhaId}:${data}`;\n    const existente = porChave.get(chave);\n    if (existente) {\n      existente.custo = Math.round((existente.custo + custo) * 100) / 100;\n    } else {\n      porChave.set(chave, {\n        googleCampanhaId,\n        campanha: campanha || `Campanha ${googleCampanhaId}`,\n        data,\n        custo: Math.round(custo * 100) / 100,\n      });\n    }\n  }\n\n  ignoradas += Math.max(0, lista.length - MAXIMO_LINHAS);\n  return { linhas: Array.from(porChave.values()), ignoradas };\n}\n\n/** Guarda os dias recebidos (atualiza o dia se ja existia). */\nexport async function salvarGastosRecebidos(linhas: LinhaGastoRecebida[]) {\n  const TAMANHO_LOTE = 200;\n  for (let i = 0; i < linhas.length; i += TAMANHO_LOTE) {\n    const lote = linhas.slice(i, i + TAMANHO_LOTE);\n    await prisma.$transaction(\n      lote.map((linha) =>\n        prisma.gastoGoogleAdsDia.upsert({\n          where: {\n            googleCampanhaId_data: { googleCampanhaId: linha.googleCampanhaId, data: linha.data },\n          },\n          create: {\n            googleCampanhaId: linha.googleCampanhaId,\n            campanhaNome: linha.campanha,\n            data: linha.data,\n            custo: linha.custo,\n          },\n          update: { campanhaNome: linha.campanha, custo: linha.custo },\n        }),\n      ),\n    );\n  }\n  return linhas.length;\n}\n\n/* ------------------------------------------------------------ lancamentos */\n\nasync function contaPrincipalId() {\n  const conta = await prisma.contaFinanceira.findFirst({\n    where: { principal: true, status: \"Ativa\" },\n    select: { id: true },\n  });\n  return conta?.id ?? null;\n}\n\nexport type ResultadoAplicacao = {\n  criados: number;\n  atualizados: number;\n  removidos: number;\n  semConta: boolean;\n};\n\n/**\n * Lanca (ou atualiza) uma saida paga por dia para cada campanha ligada ao\n * Google Ads, a partir do dia escolhido. Nunca duplica o mesmo dia.\n * Um lancamento que alguem cancelou no Financeiro continua cancelado.\n */\nexport async function aplicarGastoAutomatico(somenteCampanhaId?: number): Promise<ResultadoAplicacao> {\n  const resultado: ResultadoAplicacao = { criados: 0, atualizados: 0, removidos: 0, semConta: false };\n\n  const campanhas = await prisma.campanhaMarketing.findMany({\n    where: {\n      googleAdsCampanhaId: { not: null },\n      gastoAutomaticoDesde: { not: null },\n      ...(somenteCampanhaId ? { id: somenteCampanhaId } : {}),\n    },\n    select: { id: true, nome: true, googleAdsCampanhaId: true, gastoAutomaticoDesde: true },\n  });\n\n  if (campanhas.length === 0) return resultado;\n\n  const contaId = await contaPrincipalId();\n  if (!contaId) {\n    resultado.semConta = true;\n    return resultado;\n  }\n\n  for (const campanha of campanhas) {\n    const desde = campanha.gastoAutomaticoDesde;\n    if (!campanha.googleAdsCampanhaId || !diaValido(desde)) continue;\n\n    const prefixo = `gads:${campanha.id}:`;\n    const [dias, existentes] = await Promise.all([\n      prisma.gastoGoogleAdsDia.findMany({\n        where: { googleCampanhaId: campanha.googleAdsCampanhaId, data: { gte: desde } },\n        select: { data: true, custo: true },\n      }),\n      prisma.lancamento.findMany({\n        where: { chaveGasto: { startsWith: prefixo } },\n        select: { id: true, chaveGasto: true, valor: true, statusPagamento: true, descricao: true },\n      }),\n    ]);\n\n    const porChave = new Map(existentes.map((item) => [item.chaveGasto as string, item]));\n\n    // Se a data de inicio foi mudada para mais tarde, tira os automaticos de antes.\n    for (const item of existentes) {\n      const dia = (item.chaveGasto as string).slice(prefixo.length);\n      if (dia < desde) {\n        await prisma.lancamento.delete({ where: { id: item.id } });\n        porChave.delete(item.chaveGasto as string);\n        resultado.removidos += 1;\n      }\n    }\n\n    for (const dia of dias) {\n      const chave = `${prefixo}${dia.data}`;\n      const existente = porChave.get(chave);\n      const valor = Math.round(dia.custo * 100) / 100;\n      const descricao = `Google Ads · ${campanha.nome} · ${diaFormatado(dia.data)}`;\n\n      if (valor <= 0) {\n        if (existente && existente.statusPagamento !== \"Cancelado\") {\n          await prisma.lancamento.delete({ where: { id: existente.id } });\n          resultado.removidos += 1;\n        }\n        continue;\n      }\n\n      if (existente) {\n        if (existente.statusPagamento === \"Cancelado\") continue;\n        if (existente.valor !== valor || existente.descricao !== descricao) {\n          await prisma.lancamento.update({\n            where: { id: existente.id },\n            data: { valor, valorLiquido: valor, descricao },\n          });\n          resultado.atualizados += 1;\n        }\n        continue;\n      }\n\n      await prisma.lancamento.create({\n        data: {\n          descricao,\n          valor,\n          valorLiquido: valor,\n          tipo: \"SAIDA\",\n          categoria: \"Marketing\",\n          data: dataDoDia(dia.data),\n          statusPagamento: \"Pago\",\n          origem: ORIGEM_GASTO_AUTOMATICO,\n          campanhaId: campanha.id,\n          contaFinanceiraId: contaId,\n          chaveGasto: chave,\n          observacoes: \"Gasto do dia enviado pelo Google Ads (lançado automaticamente).\",\n        },\n      });\n      resultado.criados += 1;\n    }\n  }\n\n  return resultado;\n}\n\n/* ------------------------------------------- substituir os blocos manuais */\n\nexport type BlocoManual = {\n  id: number;\n  data: string;\n  descricao: string;\n  valor: number;\n  contaFinanceiraId: number | null;\n};\n\nexport type PreviaSubstituicao = {\n  campanhaId: number;\n  campanhaNome: string;\n  inicio: string;\n  fim: string;\n  blocos: BlocoManual[];\n  totalBlocos: number;\n  totalGoogle: number;\n  diasComGasto: number;\n};\n\n/**\n * Lancamentos manuais (blocos) de gasto da campanha ANTES do inicio do\n * automatico: saida paga, ligada a campanha, que nao foi lancada sozinha.\n */\nasync function buscarBlocosManuais(campanhaId: number, antesDe: string) {\n  const blocos = await prisma.lancamento.findMany({\n    where: {\n      campanhaId,\n      tipo: \"SAIDA\",\n      statusPagamento: \"Pago\",\n      chaveGasto: null,\n      venda: { is: null },\n      data: { lt: new Date(`${antesDe}T00:00:00-03:00`) },\n    },\n    orderBy: [{ data: \"asc\" }, { id: \"asc\" }],\n    select: { id: true, data: true, descricao: true, valor: true, contaFinanceiraId: true, observacoes: true },\n  });\n  return blocos;\n}\n\nexport async function montarPreviaSubstituicao(campanhaId: number): Promise<PreviaSubstituicao> {\n  const campanha = await prisma.campanhaMarketing.findUnique({\n    where: { id: campanhaId },\n    select: { id: true, nome: true, googleAdsCampanhaId: true, gastoAutomaticoDesde: true },\n  });\n  if (!campanha) throw new Error(\"Campanha não encontrada.\");\n  if (!campanha.googleAdsCampanhaId || !diaValido(campanha.gastoAutomaticoDesde)) {\n    throw new Error(\"Ligue esta campanha ao Google Ads e escolha o dia de início antes.\");\n  }\n\n  const desde = campanha.gastoAutomaticoDesde;\n  const fim = somarDias(desde, -1);\n  const blocos = await buscarBlocosManuais(campanha.id, desde);\n\n  const primeiroGoogle = await prisma.gastoGoogleAdsDia.findFirst({\n    where: { googleCampanhaId: campanha.googleAdsCampanhaId, data: { lte: fim }, custo: { gt: 0 } },\n    orderBy: { data: \"asc\" },\n    select: { data: true },\n  });\n  const primeiroBloco = blocos[0] ? diaDe(blocos[0].data) : null;\n  const candidatos = [primeiroGoogle?.data, primeiroBloco].filter(\n    (dia): dia is string => Boolean(dia),\n  );\n  const inicio = candidatos.length > 0 ? candidatos.sort()[0] : fim;\n\n  const diasGoogle = await prisma.gastoGoogleAdsDia.findMany({\n    where: {\n      googleCampanhaId: campanha.googleAdsCampanhaId,\n      data: { gte: inicio, lte: fim },\n      custo: { gt: 0 },\n    },\n    select: { data: true, custo: true },\n  });\n\n  return {\n    campanhaId: campanha.id,\n    campanhaNome: campanha.nome,\n    inicio,\n    fim,\n    blocos: blocos.map((bloco) => ({\n      id: bloco.id,\n      data: diaDe(bloco.data),\n      descricao: bloco.descricao,\n      valor: bloco.valor,\n      contaFinanceiraId: bloco.contaFinanceiraId,\n    })),\n    totalBlocos: Math.round(blocos.reduce((soma, bloco) => soma + bloco.valor, 0) * 100) / 100,\n    totalGoogle: Math.round(diasGoogle.reduce((soma, dia) => soma + dia.custo, 0) * 100) / 100,\n    diasComGasto: diasGoogle.length,\n  };\n}\n\n/**\n * Troca os blocos manuais por lancamentos de cada dia com o MESMO total (por\n * conta financeira), espalhado na proporcao do gasto real de cada dia. Os\n * blocos ficam guardados como \"Cancelado\" (nao contam mais), com o motivo.\n * Resultado: o saldo de cada conta continua exatamente igual.\n */\nexport async function substituirBlocosManuais(campanhaId: number, usuario: string) {\n  const previa = await montarPreviaSubstituicao(campanhaId);\n  if (previa.blocos.length === 0) {\n    return { substituidos: 0, criados: 0, total: 0 };\n  }\n\n  const campanha = await prisma.campanhaMarketing.findUnique({\n    where: { id: campanhaId },\n    select: { googleAdsCampanhaId: true },\n  });\n\n  const diasGoogle = await prisma.gastoGoogleAdsDia.findMany({\n    where: {\n      googleCampanhaId: campanha?.googleAdsCampanhaId ?? \"\",\n      data: { gte: previa.inicio, lte: previa.fim },\n      custo: { gt: 0 },\n    },\n    orderBy: { data: \"asc\" },\n    select: { data: true, custo: true },\n  });\n\n  // Sem gasto do Google nesse periodo: divide por igual entre os dias.\n  const dias = diasGoogle.length > 0 ? diasGoogle.map((dia) => dia.data) : diasEntre(previa.inicio, previa.fim);\n  const pesos = diasGoogle.length > 0 ? diasGoogle.map((dia) => dia.custo) : dias.map(() => 1);\n\n  const porConta = new Map<number | null, BlocoManual[]>();\n  for (const bloco of previa.blocos) {\n    const lista = porConta.get(bloco.contaFinanceiraId) ?? [];\n    lista.push(bloco);\n    porConta.set(bloco.contaFinanceiraId, lista);\n  }\n\n  const hoje = diaFormatado(diaDe());\n  const idsCriados: number[] = [];\n\n  await prisma.$transaction(\n    async (tx) => {\n      for (const [contaId, blocosDaConta] of porConta) {\n        const totalConta = blocosDaConta.reduce((soma, bloco) => soma + bloco.valor, 0);\n        const partes = distribuirValor(totalConta, pesos);\n\n        for (let i = 0; i < dias.length; i += 1) {\n          const valor = partes[i];\n          if (valor <= 0) continue;\n          const chave = `gads-ajuste:${previa.campanhaId}:${dias[i]}:${contaId ?? 0}`;\n\n          const existente = await tx.lancamento.findUnique({\n            where: { chaveGasto: chave },\n            select: { id: true, valor: true },\n          });\n\n          if (existente) {\n            const novoValor = Math.round((existente.valor + valor) * 100) / 100;\n            await tx.lancamento.update({\n              where: { id: existente.id },\n              data: { valor: novoValor, valorLiquido: novoValor },\n            });\n            idsCriados.push(existente.id);\n            continue;\n          }\n\n          const criado = await tx.lancamento.create({\n            data: {\n              descricao: `Google Ads · ${previa.campanhaNome} · ${diaFormatado(dias[i])}`,\n              valor,\n              valorLiquido: valor,\n              tipo: \"SAIDA\",\n              categoria: \"Marketing\",\n              data: dataDoDia(dias[i]),\n              statusPagamento: \"Pago\",\n              origem: ORIGEM_GASTO_AJUSTE,\n              campanhaId: previa.campanhaId,\n              contaFinanceiraId: contaId,\n              chaveGasto: chave,\n              observacoes:\n                \"Parte dos lançamentos manuais antigos desta campanha, redistribuída pelo gasto real de cada dia (o total continua o mesmo).\",\n            },\n            select: { id: true },\n          });\n          idsCriados.push(criado.id);\n        }\n\n        for (const bloco of blocosDaConta) {\n          const atual = await tx.lancamento.findUnique({\n            where: { id: bloco.id },\n            select: { observacoes: true, statusPagamento: true },\n          });\n          if (!atual || atual.statusPagamento !== \"Pago\") {\n            throw new Error(\"Algum lançamento mudou enquanto a troca era feita. Abra a tela de novo e tente outra vez.\");\n          }\n          await tx.lancamento.update({\n            where: { id: bloco.id },\n            data: {\n              statusPagamento: \"Cancelado\",\n              observacoes: [\n                atual.observacoes?.trim(),\n                `[Substituído em ${hoje} pelo gasto de cada dia do Google Ads (mesmo total, redistribuído por dia).]`,\n              ]\n                .filter(Boolean)\n                .join(\"\\n\"),\n            },\n          });\n        }\n      }\n\n      await tx.auditoria.create({\n        data: {\n          modulo: \"Marketing\",\n          acao: \"Substituiu blocos de custo pelo gasto diário\",\n          entidade: \"CampanhaMarketing\",\n          entidadeId: String(previa.campanhaId),\n          usuario,\n          detalhes: JSON.stringify({\n            campanha: previa.campanhaNome,\n            periodo: [previa.inicio, previa.fim],\n            total: previa.totalBlocos,\n            blocosCancelados: previa.blocos.map((bloco) => bloco.id),\n            lancamentosDiarios: Array.from(new Set(idsCriados)),\n          }),\n        },\n      });\n    },\n    { timeout: 60000, maxWait: 15000 },\n  );\n\n  return {\n    substituidos: previa.blocos.length,\n    criados: new Set(idsCriados).size,\n    total: previa.totalBlocos,\n  };\n}\n","actions/gasto-google-ads.actions.ts":"\"use server\";\n\nimport { revalidatePath } from \"next/cache\";\n\nimport { requirePermission } from \"@/lib/auth\";\nimport {\n  aplicarGastoAutomatico,\n  diaValido,\n  montarPreviaSubstituicao,\n  substituirBlocosManuais,\n  type PreviaSubstituicao,\n  type ResultadoAplicacao,\n} from \"@/lib/gasto-google-ads\";\nimport { prisma } from \"@/lib/prisma\";\n\nfunction revalidar() {\n  revalidatePath(\"/marketing\");\n  revalidatePath(\"/marketing/gasto-google-ads\");\n  revalidatePath(\"/financeiro\");\n  revalidatePath(\"/gestao\");\n  revalidatePath(\"/relatorios\");\n  revalidatePath(\"/\");\n}\n\nasync function exigirPermissoes() {\n  const usuario = await requirePermission(\"marketing.gerenciar\");\n  await requirePermission(\"financeiro.gerenciar\");\n  return usuario;\n}\n\n/**\n * Liga uma campanha do Google Ads a uma campanha do sistema (ou desliga, com\n * campanhaId null) e define a partir de que dia o gasto entra sozinho.\n */\nexport async function ligarCampanhaGoogleAds(dados: {\n  googleCampanhaId: string;\n  campanhaId: number | null;\n  desde: string;\n}): Promise<ResultadoAplicacao & { ok: true }> {\n  const usuario = await exigirPermissoes();\n\n  const googleCampanhaId = String(dados.googleCampanhaId || \"\").trim();\n  if (!/^\\d{1,20}$/.test(googleCampanhaId)) throw new Error(\"Campanha do Google inválida.\");\n\n  if (!dados.campanhaId) {\n    await prisma.campanhaMarketing.updateMany({\n      where: { googleAdsCampanhaId: googleCampanhaId },\n      data: { googleAdsCampanhaId: null, gastoAutomaticoDesde: null },\n    });\n    await prisma.auditoria.create({\n      data: {\n        modulo: \"Marketing\",\n        acao: \"Desligou campanha do Google Ads\",\n        entidade: \"CampanhaMarketing\",\n        usuario: usuario.email,\n        detalhes: `Campanha do Google ${googleCampanhaId}. Os gastos já lançados continuam no Financeiro.`,\n      },\n    });\n    revalidar();\n    return { ok: true, criados: 0, atualizados: 0, removidos: 0, semConta: false };\n  }\n\n  if (!diaValido(dados.desde)) throw new Error(\"Escolha o dia a partir do qual o gasto entra sozinho.\");\n\n  const campanha = await prisma.campanhaMarketing.findUnique({\n    where: { id: Number(dados.campanhaId) },\n    select: { id: true, nome: true },\n  });\n  if (!campanha) throw new Error(\"Campanha do sistema não encontrada.\");\n\n  await prisma.$transaction([\n    // Uma campanha do Google fica ligada a uma so campanha do sistema.\n    prisma.campanhaMarketing.updateMany({\n      where: { googleAdsCampanhaId: googleCampanhaId, NOT: { id: campanha.id } },\n      data: { googleAdsCampanhaId: null, gastoAutomaticoDesde: null },\n    }),\n    prisma.campanhaMarketing.update({\n      where: { id: campanha.id },\n      data: { googleAdsCampanhaId: googleCampanhaId, gastoAutomaticoDesde: dados.desde },\n    }),\n    prisma.auditoria.create({\n      data: {\n        modulo: \"Marketing\",\n        acao: \"Ligou campanha ao Google Ads\",\n        entidade: \"CampanhaMarketing\",\n        entidadeId: String(campanha.id),\n        usuario: usuario.email,\n        detalhes: `${campanha.nome} ← campanha do Google ${googleCampanhaId}. Gasto automático a partir de ${dados.desde}.`,\n      },\n    }),\n  ]);\n\n  const resultado = await aplicarGastoAutomatico(campanha.id);\n  revalidar();\n  return { ok: true, ...resultado };\n}\n\nexport async function previaSubstituirBlocos(campanhaId: number): Promise<PreviaSubstituicao> {\n  await exigirPermissoes();\n  return montarPreviaSubstituicao(Number(campanhaId));\n}\n\nexport async function confirmarSubstituirBlocos(campanhaId: number) {\n  const usuario = await exigirPermissoes();\n  const resultado = await substituirBlocosManuais(Number(campanhaId), usuario.email);\n  revalidar();\n  return resultado;\n}\n","app/api/marketing/gasto-google-ads/route.ts":"import { timingSafeEqual } from \"node:crypto\";\nimport { NextResponse } from \"next/server\";\nimport type { NextRequest } from \"next/server\";\n\nimport {\n  aplicarGastoAutomatico,\n  normalizarLinhasRecebidas,\n  salvarGastosRecebidos,\n} from \"@/lib/gasto-google-ads\";\nimport { prisma } from \"@/lib/prisma\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\n\n/**\n * Recebe, do script agendado dentro do Google Ads, quanto cada campanha gastou\n * em cada dia. Usa a mesma senha da exportacao de conversoes\n * (MARKETING_EXPORT_SECRET), enviada no cabecalho \"Authorization: Bearer ...\".\n */\n\nfunction comparacaoSegura(valorRecebido: string, valorEsperado: string) {\n  const recebido = Buffer.from(valorRecebido);\n  const esperado = Buffer.from(valorEsperado);\n  if (recebido.length !== esperado.length) return false;\n  return timingSafeEqual(recebido, esperado);\n}\n\nfunction extrairToken(request: NextRequest) {\n  const header = request.headers.get(\"authorization\");\n  if (header?.toLowerCase().startsWith(\"bearer \")) return header.slice(7).trim();\n  return request.headers.get(\"x-marketing-export-token\")?.trim() ?? \"\";\n}\n\nexport async function POST(request: NextRequest) {\n  const segredo = process.env.MARKETING_EXPORT_SECRET?.trim();\n\n  if (!segredo || segredo.length < 24) {\n    return NextResponse.json(\n      { ok: false, erro: \"Recebimento não configurado: falta MARKETING_EXPORT_SECRET (mínimo 24 caracteres).\" },\n      { status: 503 },\n    );\n  }\n\n  const token = extrairToken(request);\n  if (!token || !comparacaoSegura(token, segredo)) {\n    return NextResponse.json({ ok: false, erro: \"Não autorizado.\" }, { status: 401 });\n  }\n\n  let corpo: unknown;\n  try {\n    corpo = await request.json();\n  } catch {\n    return NextResponse.json({ ok: false, erro: \"Conteúdo inválido (esperado JSON).\" }, { status: 400 });\n  }\n\n  try {\n    const { linhas, ignoradas } = normalizarLinhasRecebidas(corpo);\n    await salvarGastosRecebidos(linhas);\n    const resultado = await aplicarGastoAutomatico();\n\n    // Campanhas do Google que ainda nao estao ligadas a nenhuma campanha do sistema.\n    const idsRecebidos = Array.from(new Set(linhas.map((linha) => linha.googleCampanhaId)));\n    const ligadas = await prisma.campanhaMarketing.findMany({\n      where: { googleAdsCampanhaId: { in: idsRecebidos } },\n      select: { googleAdsCampanhaId: true },\n    });\n    const idsLigados = new Set(ligadas.map((item) => item.googleAdsCampanhaId));\n    const semLigacao = Array.from(\n      new Set(\n        linhas.filter((linha) => !idsLigados.has(linha.googleCampanhaId)).map((linha) => linha.campanha),\n      ),\n    );\n\n    const resumo = `${linhas.length} dia(s) recebido(s)${ignoradas ? `, ${ignoradas} ignorado(s)` : \"\"}. Lançamentos: ${resultado.criados} novo(s), ${resultado.atualizados} atualizado(s), ${resultado.removidos} removido(s).${resultado.semConta ? \" ATENÇÃO: não há conta financeira principal ativa, nada foi lançado.\" : \"\"}`;\n\n    await prisma.auditoria.create({\n      data: {\n        modulo: \"Marketing\",\n        acao: \"Gasto do Google Ads recebido\",\n        entidade: \"GastoGoogleAdsDia\",\n        usuario: \"Script do Google Ads\",\n        detalhes: resumo,\n      },\n    });\n\n    return NextResponse.json({\n      ok: true,\n      recebidos: linhas.length,\n      ignorados: ignoradas,\n      ...resultado,\n      semLigacao,\n      resumo,\n    });\n  } catch (erro) {\n    console.error(\"[gasto-google-ads]\", erro);\n    const mensagem = erro instanceof Error ? erro.message : \"Falha ao salvar o gasto.\";\n    await prisma.auditoria\n      .create({\n        data: {\n          modulo: \"Marketing\",\n          acao: \"Falha ao receber gasto do Google Ads\",\n          entidade: \"GastoGoogleAdsDia\",\n          usuario: \"Script do Google Ads\",\n          detalhes: mensagem.slice(0, 500),\n        },\n      })\n      .catch(() => undefined);\n    return NextResponse.json({ ok: false, erro: mensagem }, { status: 500 });\n  }\n}\n\nexport async function GET() {\n  return NextResponse.json(\n    { ok: false, erro: \"Use POST (este endereço é chamado pelo script do Google Ads).\" },\n    { status: 405 },\n  );\n}\n","app/(app)/marketing/gasto-google-ads/page.tsx":"import { headers } from \"next/headers\";\n\nimport { canAccess, requirePagePermission } from \"@/lib/auth\";\nimport { diaDe, somarDias } from \"@/lib/gasto-google-ads\";\nimport { prisma } from \"@/lib/prisma\";\n\nimport GastoGoogleAdsPainel, {\n  type CampanhaGoogle,\n  type CampanhaSistema,\n} from \"./components/GastoGoogleAdsPainel\";\n\nexport const dynamic = \"force-dynamic\";\n\nfunction arredondar(valor: number) {\n  return Math.round(valor * 100) / 100;\n}\n\nexport default async function GastoGoogleAdsPage() {\n  const usuario = await requirePagePermission(\"marketing.visualizar\");\n  const podeGerenciar =\n    canAccess(usuario, \"marketing.gerenciar\") && canAccess(usuario, \"financeiro.gerenciar\");\n\n  const hoje = diaDe();\n  const inicio30 = somarDias(hoje, -30);\n\n  const [porCampanha, ultimos30, nomes, ultimoRecebimento, campanhas, manuais, automaticos] =\n    await Promise.all([\n      prisma.gastoGoogleAdsDia.groupBy({\n        by: [\"googleCampanhaId\"],\n        _min: { data: true },\n        _max: { data: true },\n        _sum: { custo: true },\n      }),\n      prisma.gastoGoogleAdsDia.groupBy({\n        by: [\"googleCampanhaId\"],\n        where: { data: { gte: inicio30 } },\n        _sum: { custo: true },\n      }),\n      prisma.gastoGoogleAdsDia.findMany({\n        orderBy: { data: \"desc\" },\n        distinct: [\"googleCampanhaId\"],\n        select: { googleCampanhaId: true, campanhaNome: true },\n      }),\n      prisma.auditoria.findFirst({\n        where: {\n          modulo: \"Marketing\",\n          acao: { in: [\"Gasto do Google Ads recebido\", \"Falha ao receber gasto do Google Ads\"] },\n        },\n        orderBy: { createdAt: \"desc\" },\n        select: { acao: true, detalhes: true, createdAt: true },\n      }),\n      prisma.campanhaMarketing.findMany({\n        orderBy: [{ status: \"asc\" }, { nome: \"asc\" }],\n        select: {\n          id: true,\n          nome: true,\n          canal: true,\n          status: true,\n          googleAdsCampanhaId: true,\n          gastoAutomaticoDesde: true,\n        },\n      }),\n      // Gastos lancados a mao (blocos) ligados a campanhas.\n      prisma.lancamento.findMany({\n        where: {\n          campanhaId: { not: null },\n          tipo: \"SAIDA\",\n          statusPagamento: \"Pago\",\n          chaveGasto: null,\n          venda: { is: null },\n        },\n        select: { campanhaId: true, data: true, valor: true },\n      }),\n      prisma.lancamento.findMany({\n        where: {\n          campanhaId: { not: null },\n          statusPagamento: \"Pago\",\n          chaveGasto: { startsWith: \"gads:\" },\n        },\n        select: { campanhaId: true, valor: true },\n      }),\n    ]);\n\n  const nomePorId = new Map(nomes.map((item) => [item.googleCampanhaId, item.campanhaNome]));\n  const trintaPorId = new Map(ultimos30.map((item) => [item.googleCampanhaId, item._sum.custo ?? 0]));\n\n  const campanhasGoogle: CampanhaGoogle[] = porCampanha\n    .map((item) => ({\n      googleCampanhaId: item.googleCampanhaId,\n      nome: nomePorId.get(item.googleCampanhaId) ?? `Campanha ${item.googleCampanhaId}`,\n      primeiroDia: item._min.data ?? hoje,\n      ultimoDia: item._max.data ?? hoje,\n      total: arredondar(item._sum.custo ?? 0),\n      ultimos30: arredondar(trintaPorId.get(item.googleCampanhaId) ?? 0),\n    }))\n    .sort((a, b) => b.ultimos30 - a.ultimos30 || a.nome.localeCompare(b.nome));\n\n  const campanhasSistema: CampanhaSistema[] = campanhas.map((campanha) => {\n    const doCampanha = manuais.filter((item) => item.campanhaId === campanha.id);\n    const ultimoManual = doCampanha.reduce<Date | null>(\n      (maior, item) => (!maior || item.data > maior ? item.data : maior),\n      null,\n    );\n    const desde = campanha.gastoAutomaticoDesde;\n    const limite = desde ? new Date(`${desde}T00:00:00-03:00`) : null;\n    const antes = limite ? doCampanha.filter((item) => item.data < limite) : [];\n    const depois = limite ? doCampanha.filter((item) => item.data >= limite) : [];\n    const autos = automaticos.filter((item) => item.campanhaId === campanha.id);\n\n    return {\n      id: campanha.id,\n      nome: campanha.nome,\n      canal: campanha.canal,\n      status: campanha.status,\n      googleAdsCampanhaId: campanha.googleAdsCampanhaId,\n      gastoAutomaticoDesde: desde,\n      ultimoManualDia: ultimoManual ? diaDe(ultimoManual) : null,\n      manuaisAntes: {\n        quantidade: antes.length,\n        total: arredondar(antes.reduce((soma, item) => soma + item.valor, 0)),\n      },\n      manuaisDepois: {\n        quantidade: depois.length,\n        total: arredondar(depois.reduce((soma, item) => soma + item.valor, 0)),\n      },\n      automaticos: {\n        quantidade: autos.length,\n        total: arredondar(autos.reduce((soma, item) => soma + item.valor, 0)),\n      },\n    };\n  });\n\n  const cabecalhos = await headers();\n  const host = cabecalhos.get(\"x-forwarded-host\") ?? cabecalhos.get(\"host\") ?? \"app.studiorealcar.com.br\";\n  const protocolo = cabecalhos.get(\"x-forwarded-proto\") ?? \"https\";\n\n  return (\n    <GastoGoogleAdsPainel\n      campanhasGoogle={campanhasGoogle}\n      campanhasSistema={campanhasSistema}\n      endereco={`${protocolo}://${host}/api/marketing/gasto-google-ads`}\n      ultimoRecebimento={\n        ultimoRecebimento\n          ? {\n              ok: ultimoRecebimento.acao === \"Gasto do Google Ads recebido\",\n              detalhes: ultimoRecebimento.detalhes,\n              data: ultimoRecebimento.createdAt.toISOString(),\n            }\n          : null\n      }\n      hoje={hoje}\n      podeGerenciar={podeGerenciar}\n    />\n  );\n}\n","app/(app)/marketing/gasto-google-ads/components/GastoGoogleAdsPainel.tsx":"\"use client\";\n\nimport { useState, useTransition } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  AlertTriangle,\n  ArrowLeft,\n  CheckCircle2,\n  Link2,\n  Loader2,\n  Repeat2,\n} from \"lucide-react\";\n\nimport {\n  confirmarSubstituirBlocos,\n  ligarCampanhaGoogleAds,\n  previaSubstituirBlocos,\n} from \"@/actions/gasto-google-ads.actions\";\nimport type { PreviaSubstituicao } from \"@/lib/gasto-google-ads\";\n\nexport type CampanhaGoogle = {\n  googleCampanhaId: string;\n  nome: string;\n  primeiroDia: string;\n  ultimoDia: string;\n  total: number;\n  ultimos30: number;\n};\n\nexport type CampanhaSistema = {\n  id: number;\n  nome: string;\n  canal: string;\n  status: string;\n  googleAdsCampanhaId: string | null;\n  gastoAutomaticoDesde: string | null;\n  ultimoManualDia: string | null;\n  manuaisAntes: { quantidade: number; total: number };\n  manuaisDepois: { quantidade: number; total: number };\n  automaticos: { quantidade: number; total: number };\n};\n\ntype Props = {\n  campanhasGoogle: CampanhaGoogle[];\n  campanhasSistema: CampanhaSistema[];\n  endereco: string;\n  ultimoRecebimento: { ok: boolean; detalhes: string | null; data: string } | null;\n  hoje: string;\n  podeGerenciar: boolean;\n};\n\nfunction moeda(valor: number) {\n  return valor.toLocaleString(\"pt-BR\", { style: \"currency\", currency: \"BRL\" });\n}\n\nfunction dia(valor: string | null) {\n  if (!valor) return \"-\";\n  const [ano, mes, d] = valor.split(\"-\");\n  return `${d}/${mes}/${ano}`;\n}\n\nfunction proximoDia(valor: string) {\n  const [ano, mes, d] = valor.split(\"-\").map(Number);\n  return new Date(Date.UTC(ano, mes - 1, d + 1)).toISOString().slice(0, 10);\n}\n\nfunction dataHora(valor: string) {\n  return new Date(valor).toLocaleString(\"pt-BR\", {\n    day: \"2-digit\",\n    month: \"2-digit\",\n    year: \"2-digit\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    timeZone: \"America/Sao_Paulo\",\n  });\n}\n\nfunction mensagemErro(erro: unknown, padrao: string) {\n  return erro instanceof Error && erro.message ? erro.message : padrao;\n}\n\nconst cartao =\n  \"rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-white/10 dark:bg-white/[0.06] sm:rounded-3xl sm:p-6\";\n\nexport default function GastoGoogleAdsPainel({\n  campanhasGoogle,\n  campanhasSistema,\n  endereco,\n  ultimoRecebimento,\n  hoje,\n  podeGerenciar,\n}: Props) {\n  return (\n    <div className=\"app-mobile-safe space-y-4 pb-6 sm:space-y-6 sm:pb-0\">\n      <section className={cartao}>\n        <Link\n          href=\"/marketing\"\n          className=\"inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-violet-700 dark:text-slate-400\"\n        >\n          <ArrowLeft size={14} /> Voltar para Marketing\n        </Link>\n        <h1 className=\"mt-3 text-xl font-bold tracking-tight text-slate-900 dark:text-white sm:text-3xl\">\n          Gasto diário do Google Ads\n        </h1>\n        <p className=\"mt-2 max-w-3xl text-sm leading-6 text-slate-600 dark:text-slate-400\">\n          Todo dia o Google Ads manda quanto cada campanha gastou em cada dia. O sistema lança sozinho no\n          Financeiro uma saída paga por dia, na data certa, saindo da conta principal. Assim &ldquo;últimos 7\n          dias&rdquo; e &ldquo;últimos 30 dias&rdquo; mostram o gasto do dia em que ele aconteceu.\n        </p>\n\n        <div className=\"mt-4 rounded-2xl border border-slate-200 bg-slate-50 p-3 text-sm dark:border-white/10 dark:bg-white/[0.04]\">\n          {ultimoRecebimento ? (\n            <p\n              className={\n                ultimoRecebimento.ok ? \"text-slate-700 dark:text-slate-200\" : \"font-semibold text-rose-700\"\n              }\n            >\n              {ultimoRecebimento.ok ? \"Último envio do Google Ads: \" : \"O último envio FALHOU: \"}\n              {dataHora(ultimoRecebimento.data)}.{\" \"}\n              <span className=\"text-xs text-slate-500 dark:text-slate-400\">{ultimoRecebimento.detalhes}</span>\n            </p>\n          ) : (\n            <p className=\"font-semibold text-amber-700 dark:text-amber-300\">\n              O Google Ads ainda não mandou nenhum gasto. Falta colar e agendar o script no Google Ads.\n            </p>\n          )}\n          <p className=\"mt-2 break-all text-xs text-slate-500 dark:text-slate-400\">\n            Endereço que o script usa: <span className=\"font-mono\">{endereco}</span> · senha: a mesma da\n            exportação de conversões (MARKETING_EXPORT_SECRET).\n          </p>\n        </div>\n      </section>\n\n      {campanhasGoogle.length === 0 ? null : (\n        <section className={cartao}>\n          <h2 className=\"text-lg font-bold text-slate-900 dark:text-white\">Campanhas do Google Ads</h2>\n          <p className=\"mt-1 text-sm text-slate-600 dark:text-slate-400\">\n            Ligue cada campanha do Google à campanha certa do sistema e escolha a partir de que dia o gasto entra\n            sozinho. Use o dia seguinte ao último custo que você lançou à mão, para não somar duas vezes.\n          </p>\n          <div className=\"mt-4 space-y-4\">\n            {campanhasGoogle.map((google) => (\n              <CartaoCampanhaGoogle\n                key={google.googleCampanhaId}\n                google={google}\n                campanhasSistema={campanhasSistema}\n                hoje={hoje}\n                podeGerenciar={podeGerenciar}\n              />\n            ))}\n          </div>\n        </section>\n      )}\n    </div>\n  );\n}\n\nfunction CartaoCampanhaGoogle({\n  google,\n  campanhasSistema,\n  hoje,\n  podeGerenciar,\n}: {\n  google: CampanhaGoogle;\n  campanhasSistema: CampanhaSistema[];\n  hoje: string;\n  podeGerenciar: boolean;\n}) {\n  const router = useRouter();\n  const [pendente, iniciar] = useTransition();\n  const ligada = campanhasSistema.find((item) => item.googleAdsCampanhaId === google.googleCampanhaId) ?? null;\n\n  const [campanhaId, setCampanhaId] = useState<string>(ligada ? String(ligada.id) : \"\");\n  const [desde, setDesde] = useState<string>(\n    ligada?.gastoAutomaticoDesde ?? sugerirInicio(null, google),\n  );\n  const [mensagem, setMensagem] = useState<{ tipo: \"ok\" | \"erro\"; texto: string } | null>(null);\n\n  function sugerirInicio(campanha: CampanhaSistema | null, campanhaGoogle: CampanhaGoogle) {\n    if (campanha?.gastoAutomaticoDesde) return campanha.gastoAutomaticoDesde;\n    if (campanha?.ultimoManualDia) {\n      const seguinte = proximoDia(campanha.ultimoManualDia);\n      return seguinte > hoje ? hoje : seguinte;\n    }\n    return campanhaGoogle.primeiroDia;\n  }\n\n  function escolherCampanha(valor: string) {\n    setCampanhaId(valor);\n    setMensagem(null);\n    const campanha = campanhasSistema.find((item) => String(item.id) === valor) ?? null;\n    setDesde(sugerirInicio(campanha, google));\n  }\n\n  function salvar() {\n    setMensagem(null);\n    iniciar(async () => {\n      try {\n        const resultado = await ligarCampanhaGoogleAds({\n          googleCampanhaId: google.googleCampanhaId,\n          campanhaId: campanhaId ? Number(campanhaId) : null,\n          desde,\n        });\n        setMensagem({\n          tipo: resultado.semConta ? \"erro\" : \"ok\",\n          texto: resultado.semConta\n            ? \"Salvo, mas não há conta financeira principal ativa: nada foi lançado. Marque uma conta como principal no Financeiro.\"\n            : campanhaId\n              ? `Salvo. Lançamentos: ${resultado.criados} novo(s), ${resultado.atualizados} atualizado(s), ${resultado.removidos} removido(s).`\n              : \"Campanha desligada. O que já foi lançado continua no Financeiro.\",\n        });\n        router.refresh();\n      } catch (erro) {\n        setMensagem({ tipo: \"erro\", texto: mensagemErro(erro, \"Não foi possível salvar.\") });\n      }\n    });\n  }\n\n  // Campanha escolhida agora (ainda nao salva), para mostrar a dica do dia de inicio.\n  const escolhidaNova =\n    campanhaId && String(ligada?.id ?? \"\") !== campanhaId\n      ? (campanhasSistema.find((item) => String(item.id) === campanhaId) ?? null)\n      : null;\n\n  const mudou =\n    campanhaId !== (ligada ? String(ligada.id) : \"\") ||\n    (Boolean(campanhaId) && desde !== (ligada?.gastoAutomaticoDesde ?? \"\"));\n\n  return (\n    <article className=\"rounded-2xl border border-slate-200 bg-slate-50 p-4 dark:border-white/10 dark:bg-white/[0.04]\">\n      <div className=\"flex flex-wrap items-start justify-between gap-2\">\n        <div className=\"min-w-0\">\n          <p className=\"break-words font-bold text-slate-900 dark:text-white\">{google.nome}</p>\n          <p className=\"mt-0.5 text-xs text-slate-500 dark:text-slate-400\">\n            Dados de {dia(google.primeiroDia)} a {dia(google.ultimoDia)} · nº {google.googleCampanhaId}\n          </p>\n        </div>\n        <div className=\"text-right text-sm\">\n          <p className=\"font-bold text-slate-900 dark:text-white\">{moeda(google.ultimos30)}</p>\n          <p className=\"text-[11px] text-slate-500 dark:text-slate-400\">gasto nos últimos 30 dias</p>\n        </div>\n      </div>\n\n      {podeGerenciar ? (\n        <div className=\"mt-3 grid gap-3 sm:grid-cols-[1fr_auto_auto] sm:items-end\">\n          <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n            Campanha do sistema\n            <select\n              value={campanhaId}\n              onChange={(evento) => escolherCampanha(evento.target.value)}\n              className=\"h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 dark:border-white/10 dark:bg-slate-900 dark:text-white\"\n            >\n              <option value=\"\">Não ligar (não lança nada)</option>\n              {campanhasSistema.map((campanha) => (\n                <option key={campanha.id} value={campanha.id}>\n                  {campanha.nome}\n                  {campanha.status !== \"Ativa\" ? ` (${campanha.status})` : \"\"}\n                </option>\n              ))}\n            </select>\n          </label>\n          <label className=\"grid gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300\">\n            Lançar sozinho a partir de\n            <input\n              type=\"date\"\n              value={desde}\n              onChange={(evento) => setDesde(evento.target.value)}\n              disabled={!campanhaId}\n              className=\"h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-900 disabled:opacity-50 dark:border-white/10 dark:bg-slate-900 dark:text-white\"\n            />\n          </label>\n          <button\n            type=\"button\"\n            onClick={salvar}\n            disabled={pendente || !mudou || (Boolean(campanhaId) && !desde)}\n            className=\"inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white shadow-sm hover:bg-violet-700 disabled:opacity-50\"\n          >\n            {pendente ? <Loader2 className=\"size-4 animate-spin\" /> : <Link2 className=\"size-4\" />}\n            Salvar\n          </button>\n        </div>\n      ) : (\n        <p className=\"mt-3 text-sm text-slate-600 dark:text-slate-300\">\n          {ligada ? `Ligada a: ${ligada.nome}` : \"Ainda não ligada a nenhuma campanha do sistema.\"}\n        </p>\n      )}\n\n      {escolhidaNova?.ultimoManualDia ? (\n        <p className=\"mt-2 text-xs text-slate-500 dark:text-slate-400\">\n          Último custo lançado à mão nessa campanha: {dia(escolhidaNova.ultimoManualDia)}. Por isso a sugestão é\n          começar em {dia(proximoDia(escolhidaNova.ultimoManualDia))}.\n        </p>\n      ) : null}\n\n      {mensagem ? (\n        <p\n          className={`mt-3 rounded-xl px-3 py-2 text-xs font-semibold ${\n            mensagem.tipo === \"ok\" ? \"bg-emerald-50 text-emerald-800\" : \"bg-rose-50 text-rose-700\"\n          }`}\n        >\n          {mensagem.texto}\n        </p>\n      ) : null}\n\n      {ligada ? <SituacaoLigada campanha={ligada} podeGerenciar={podeGerenciar} /> : null}\n    </article>\n  );\n}\n\nfunction SituacaoLigada({ campanha, podeGerenciar }: { campanha: CampanhaSistema; podeGerenciar: boolean }) {\n  const router = useRouter();\n  const [pendente, iniciar] = useTransition();\n  const [previa, setPrevia] = useState<PreviaSubstituicao | null>(null);\n  const [mensagem, setMensagem] = useState<{ tipo: \"ok\" | \"erro\"; texto: string } | null>(null);\n\n  function verPrevia() {\n    setMensagem(null);\n    iniciar(async () => {\n      try {\n        setPrevia(await previaSubstituirBlocos(campanha.id));\n      } catch (erro) {\n        setMensagem({ tipo: \"erro\", texto: mensagemErro(erro, \"Não foi possível montar a prévia.\") });\n      }\n    });\n  }\n\n  function confirmar() {\n    setMensagem(null);\n    iniciar(async () => {\n      try {\n        const resultado = await confirmarSubstituirBlocos(campanha.id);\n        setPrevia(null);\n        setMensagem({\n          tipo: \"ok\",\n          texto: `Pronto: ${resultado.substituidos} lançamento(s) manual(is) trocado(s) por ${resultado.criados} lançamento(s) por dia, somando os mesmos ${moeda(resultado.total)}. O saldo não mudou.`,\n        });\n        router.refresh();\n      } catch (erro) {\n        setMensagem({ tipo: \"erro\", texto: mensagemErro(erro, \"Não foi possível substituir.\") });\n      }\n    });\n  }\n\n  const diferenca = previa ? Math.round((previa.totalGoogle - previa.totalBlocos) * 100) / 100 : 0;\n\n  return (\n    <div className=\"mt-3 space-y-2 border-t border-slate-200 pt-3 text-sm dark:border-white/10\">\n      <p className=\"flex items-start gap-2 text-slate-700 dark:text-slate-200\">\n        <CheckCircle2 className=\"mt-0.5 size-4 shrink-0 text-emerald-600\" />\n        <span>\n          Ligada a <strong>{campanha.nome}</strong>. Gasto lançado sozinho desde {dia(campanha.gastoAutomaticoDesde)}:{\" \"}\n          {campanha.automaticos.quantidade} dia(s), {moeda(campanha.automaticos.total)}.\n        </span>\n      </p>\n\n      {campanha.manuaisDepois.quantidade > 0 ? (\n        <p className=\"flex items-start gap-2 rounded-xl bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-800 dark:bg-rose-500/10 dark:text-rose-200\">\n          <AlertTriangle className=\"mt-0.5 size-4 shrink-0\" />\n          <span>\n            Atenção: há {campanha.manuaisDepois.quantidade} custo(s) lançado(s) à mão a partir de{\" \"}\n            {dia(campanha.gastoAutomaticoDesde)} ({moeda(campanha.manuaisDepois.total)}). Eles somam junto com o gasto\n            automático (gasto em dobro). Cancele-os no Financeiro, ou mude o dia de início para depois deles.\n          </span>\n        </p>\n      ) : null}\n\n      {campanha.manuaisAntes.quantidade > 0 ? (\n        <div className=\"rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900 dark:border-amber-400/20 dark:bg-amber-500/10 dark:text-amber-100\">\n          <p className=\"font-semibold\">\n            Há {campanha.manuaisAntes.quantidade} custo(s) lançado(s) à mão em bloco antes de{\" \"}\n            {dia(campanha.gastoAutomaticoDesde)}, somando {moeda(campanha.manuaisAntes.total)}.\n          </p>\n          <p className=\"mt-1\">\n            Dá para trocar esses blocos pelo gasto de cada dia: o mesmo total é espalhado pelos dias em que o Google\n            mostra gasto. O saldo continua igual; só a data de cada parte fica certa.\n          </p>\n\n          {podeGerenciar && !previa ? (\n            <button\n              type=\"button\"\n              onClick={verPrevia}\n              disabled={pendente}\n              className=\"mt-2 inline-flex h-9 items-center gap-2 rounded-lg bg-amber-600 px-3 text-xs font-bold text-white hover:bg-amber-700 disabled:opacity-60\"\n            >\n              {pendente ? <Loader2 className=\"size-3.5 animate-spin\" /> : <Repeat2 className=\"size-3.5\" />}\n              Ver como fica\n            </button>\n          ) : null}\n\n          {previa ? (\n            <div className=\"mt-3 space-y-2 rounded-lg bg-white/70 p-3 text-slate-800 dark:bg-slate-900/60 dark:text-slate-100\">\n              <p>\n                Período: <strong>{dia(previa.inicio)}</strong> a <strong>{dia(previa.fim)}</strong> ·{\" \"}\n                {previa.diasComGasto > 0\n                  ? `${previa.diasComGasto} dia(s) com gasto no Google`\n                  : \"sem gasto do Google nesse período (vai dividir por igual entre os dias)\"}\n              </p>\n              <ul className=\"max-h-40 space-y-0.5 overflow-y-auto\">\n                {previa.blocos.map((bloco) => (\n                  <li key={bloco.id} className=\"flex justify-between gap-2\">\n                    <span className=\"min-w-0 truncate\">\n                      {dia(bloco.data)} · {bloco.descricao}\n                    </span>\n                    <span className=\"shrink-0 font-semibold\">{moeda(bloco.valor)}</span>\n                  </li>\n                ))}\n              </ul>\n              <p>\n                Lançado à mão: <strong>{moeda(previa.totalBlocos)}</strong> → continua{\" \"}\n                <strong>{moeda(previa.totalBlocos)}</strong>, agora dividido por dia.\n              </p>\n              <p className=\"text-slate-500 dark:text-slate-400\">\n                Só para conferência: o Google mostra {moeda(previa.totalGoogle)} nesse período\n                {Math.abs(diferenca) >= 0.01\n                  ? ` (${diferenca > 0 ? \"mais\" : \"menos\"} ${moeda(Math.abs(diferenca))} que o lançado). Esse valor não muda o saldo.`\n                  : \", igual ao lançado.\"}\n              </p>\n              <div className=\"flex flex-wrap gap-2\">\n                <button\n                  type=\"button\"\n                  onClick={confirmar}\n                  disabled={pendente}\n                  className=\"inline-flex h-9 items-center gap-2 rounded-lg bg-amber-600 px-3 text-xs font-bold text-white hover:bg-amber-700 disabled:opacity-60\"\n                >\n                  {pendente ? <Loader2 className=\"size-3.5 animate-spin\" /> : <Repeat2 className=\"size-3.5\" />}\n                  Trocar os blocos pelo gasto de cada dia\n                </button>\n                <button\n                  type=\"button\"\n                  onClick={() => setPrevia(null)}\n                  disabled={pendente}\n                  className=\"inline-flex h-9 items-center rounded-lg border border-slate-300 px-3 text-xs font-semibold dark:border-white/20\"\n                >\n                  Agora não\n                </button>\n              </div>\n            </div>\n          ) : null}\n        </div>\n      ) : null}\n\n      {mensagem ? (\n        <p\n          className={`rounded-xl px-3 py-2 text-xs font-semibold ${\n            mensagem.tipo === \"ok\" ? \"bg-emerald-50 text-emerald-800\" : \"bg-rose-50 text-rose-700\"\n          }`}\n        >\n          {mensagem.texto}\n        </p>\n      ) : null}\n    </div>\n  );\n}\n","prisma/migrations/20261015120000_gasto_google_ads/migration.sql":"-- Gasto diario do Google Ads: recebido todo dia pelo script do Google Ads e\n-- lancado no Financeiro um por campanha por dia, na data certa.\nCREATE TABLE \"GastoGoogleAdsDia\" (\n    \"id\" SERIAL NOT NULL,\n    \"googleCampanhaId\" TEXT NOT NULL,\n    \"campanhaNome\" TEXT NOT NULL,\n    \"data\" TEXT NOT NULL,\n    \"custo\" DOUBLE PRECISION NOT NULL,\n    \"createdAt\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updatedAt\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"GastoGoogleAdsDia_pkey\" PRIMARY KEY (\"id\")\n);\n\nCREATE UNIQUE INDEX \"GastoGoogleAdsDia_googleCampanhaId_data_key\" ON \"GastoGoogleAdsDia\"(\"googleCampanhaId\", \"data\");\nCREATE INDEX \"GastoGoogleAdsDia_data_idx\" ON \"GastoGoogleAdsDia\"(\"data\");\n\nALTER TABLE \"CampanhaMarketing\" ADD COLUMN \"googleAdsCampanhaId\" TEXT;\nALTER TABLE \"CampanhaMarketing\" ADD COLUMN \"gastoAutomaticoDesde\" TEXT;\nCREATE UNIQUE INDEX \"CampanhaMarketing_googleAdsCampanhaId_key\" ON \"CampanhaMarketing\"(\"googleAdsCampanhaId\");\n\nALTER TABLE \"Lancamento\" ADD COLUMN \"chaveGasto\" TEXT;\nCREATE UNIQUE INDEX \"Lancamento_chaveGasto_key\" ON \"Lancamento\"(\"chaveGasto\");\n"},"arquivos":[{"arquivo":"prisma/schema.prisma","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"  competencia              String?\n  vencimento               DateTime?\n","depois":"  competencia              String?\n  vencimento               DateTime?\n\n  // Gasto de anuncio lancado sozinho, um por campanha por dia (ex.:\n  // \"gads:3:2026-10-14\"). Serve para atualizar o mesmo dia sem duplicar.\n  chaveGasto               String?  @unique\n"},{"nome":"ajuste 2","antes":"  observacoes       String?\n  leadsRelacionados Lead[]","depois":"  observacoes       String?\n  // Ligacao com a campanha no Google Ads (numero da campanha la) e a partir de\n  // que dia (\"2026-10-15\") o gasto diario passa a ser lancado sozinho.\n  googleAdsCampanhaId  String? @unique\n  gastoAutomaticoDesde String?\n  leadsRelacionados Lead[]"},{"nome":"ajuste 3","antes":"model ContaFixa {","depois":"// Gasto de cada campanha em cada dia, do jeito que o Google Ads mandou\n// (o script agendado dentro do Google Ads envia todo dia).\nmodel GastoGoogleAdsDia {\n  id               Int      @id @default(autoincrement())\n  googleCampanhaId String\n  campanhaNome     String\n  data             String\n  custo            Float\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@unique([googleCampanhaId, data])\n  @@index([data])\n}\n\nmodel ContaFixa {"}]},{"arquivo":"middleware.ts","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"  if (isBackupAutomatico || isCapturaClique || isExportarConversoes) {","depois":"  // Rota chamada pelo script agendado dentro do Google Ads para mandar o gasto\n  // de cada dia. Tem sua propria autenticacao (MARKETING_EXPORT_SECRET).\n  //\n  // IMPORTANTE:\n  // liberar somente este caminho exato.\n  const isGastoGoogleAds = pathname === \"/api/marketing/gasto-google-ads\";\n\n  if (isBackupAutomatico || isCapturaClique || isExportarConversoes || isGastoGoogleAds) {"}]},{"arquivo":"actions/lancamento.actions.ts","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"      contaFixaId: true,\n      venda: { select: { id: true } },","depois":"      contaFixaId: true,\n      chaveGasto: true,\n      venda: { select: { id: true } },"},{"nome":"ajuste 2","antes":"  await prisma.lancamento.delete({ where: { id } });\n  revalidarFinanceiro(existente.clienteId);\n\n  return { ok: true, mensagem: \"Lançamento excluído.\" };","depois":"  // Gasto diario do Google Ads: cancela em vez de apagar, senao o proximo\n  // envio do Google lancaria o mesmo dia de novo.\n  if (existente.chaveGasto) {\n    await prisma.lancamento.update({\n      where: { id },\n      data: { statusPagamento: \"Cancelado\" },\n    });\n    revalidarFinanceiro(existente.clienteId);\n    return { ok: true, mensagem: \"Gasto do dia cancelado (ele não será lançado de novo).\" };\n  }\n\n  await prisma.lancamento.delete({ where: { id } });\n  revalidarFinanceiro(existente.clienteId);\n\n  return { ok: true, mensagem: \"Lançamento excluído.\" };"}]},{"arquivo":"actions/marketing.actions.ts","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"  valor: number;\n  data: string;\n  contaFinanceiraId?: number | null;\n  observacoes?: string;\n}) {\n  const usuario = await requirePermission(\"marketing.gerenciar\");\n  await requirePermission(\"financeiro.gerenciar\");","depois":"  valor: number;\n  data: string;\n  // Opcional: ultimo dia do periodo. Com ele, o valor e dividido por igual\n  // entre os dias (um lancamento por dia), em vez de ficar todo num dia so.\n  dataFim?: string | null;\n  contaFinanceiraId?: number | null;\n  observacoes?: string;\n}) {\n  const usuario = await requirePermission(\"marketing.gerenciar\");\n  await requirePermission(\"financeiro.gerenciar\");"},{"nome":"ajuste 2","antes":"  const lancamento = await prisma.lancamento.create({\n    data: {\n      descricao: dados.descricao.trim(),\n      valor,\n      valorLiquido: valor,\n      tipo: \"SAIDA\",\n      categoria: \"Marketing\",\n      observacoes: limparTexto(dados.observacoes),\n      data: new Date(`${dados.data}T12:00:00-03:00`),\n      statusPagamento: \"Pago\",\n      origem: \"Marketing\",\n      campanhaId: campanha.id,\n      contaFinanceiraId: contaId,\n    },\n  });","depois":"  // Custo por periodo: espalha o valor pelos dias (de \"data\" ate \"dataFim\").\n  const dataFim = dados.dataFim?.trim() || \"\";\n  if (dataFim && diaValido(dados.data) && diaValido(dataFim) && dataFim > dados.data) {\n    const dias = diasEntre(dados.data, dataFim);\n    if (dias.length > 120) throw new Error(\"O período pode ter no máximo 120 dias.\");\n    const partes = distribuirValor(valor, dias.map(() => 1));\n\n    const criados = await prisma.$transaction(\n      dias.map((dia, indice) =>\n        prisma.lancamento.create({\n          data: {\n            descricao: `${dados.descricao.trim()} (dia ${indice + 1}/${dias.length})`,\n            valor: partes[indice],\n            valorLiquido: partes[indice],\n            tipo: \"SAIDA\",\n            categoria: \"Marketing\",\n            observacoes: limparTexto(\n              [dados.observacoes, `Parte de ${valor.toFixed(2)} dividido de ${dados.data} a ${dataFim}.`]\n                .filter(Boolean)\n                .join(\" \"),\n            ),\n            data: new Date(`${dia}T12:00:00-03:00`),\n            statusPagamento: \"Pago\",\n            origem: \"Marketing\",\n            campanhaId: campanha.id,\n            contaFinanceiraId: contaId,\n          },\n          select: { id: true },\n        }),\n      ),\n    );\n\n    await prisma.auditoria.create({\n      data: {\n        modulo: \"Marketing\",\n        acao: \"Lançou custo de campanha por período\",\n        entidade: \"CampanhaMarketing\",\n        entidadeId: String(campanha.id),\n        usuario: usuario.email,\n        detalhes: `${campanha.nome}. R$ ${valor.toFixed(2)} de ${dados.data} a ${dataFim} (${dias.length} dias). Lançamentos: ${criados.map((item) => item.id).join(\", \")}.`,\n      },\n    });\n\n    revalidatePath(\"/marketing\");\n    revalidatePath(\"/financeiro\");\n    revalidatePath(\"/gestao\");\n    revalidatePath(\"/\");\n\n    return { ok: true, lancamentoId: criados[0]?.id ?? 0 };\n  }\n\n  const lancamento = await prisma.lancamento.create({\n    data: {\n      descricao: dados.descricao.trim(),\n      valor,\n      valorLiquido: valor,\n      tipo: \"SAIDA\",\n      categoria: \"Marketing\",\n      observacoes: limparTexto(dados.observacoes),\n      data: new Date(`${dados.data}T12:00:00-03:00`),\n      statusPagamento: \"Pago\",\n      origem: \"Marketing\",\n      campanhaId: campanha.id,\n      contaFinanceiraId: contaId,\n    },\n  });"},{"nome":"ajuste 3","antes":"import { prisma } from \"@/lib/prisma\";\nimport { SINAL_PADRAO, sincronizarSinalNoTx } from \"@/lib/sinal\";","depois":"import { prisma } from \"@/lib/prisma\";\nimport { diaValido, diasEntre, distribuirValor } from \"@/lib/gasto-google-ads\";\nimport { SINAL_PADRAO, sincronizarSinalNoTx } from \"@/lib/sinal\";"}]},{"arquivo":"app/(app)/marketing/components/MarketingClient.tsx","obrigatorio":true,"patches":[{"nome":"ajuste 1","antes":"  onSubmit: (dados: { descricao: string; valor: number; data: string; contaFinanceiraId: number | null; observacoes?: string }) => void;\n}) {\n  const [descricao, setDescricao] = useState(\"\");\n  const [valor, setValor] = useState(\"\");\n  const [data, setData] = useState(hojeInput());","depois":"  onSubmit: (dados: { descricao: string; valor: number; data: string; dataFim?: string | null; contaFinanceiraId: number | null; observacoes?: string }) => void;\n}) {\n  const [descricao, setDescricao] = useState(\"\");\n  const [valor, setValor] = useState(\"\");\n  const [data, setData] = useState(hojeInput());\n  // Opcional: ultimo dia do periodo. Com ele o valor e dividido pelos dias.\n  const [dataFim, setDataFim] = useState(\"\");"},{"nome":"ajuste 2","antes":"setValor(\"\"); setData(hojeInput()); setContaId(","depois":"setValor(\"\"); setData(hojeInput()); setDataFim(\"\"); setContaId("},{"nome":"ajuste 3","antes":"        <div className=\"grid gap-4 sm:grid-cols-2\"><Input label=\"Valor pago\" type=\"number\" min=\"0.01\" step=\"0.01\" value={valor} onChange={setValor} /><Input label=\"Data\" type=\"date\" value={data} onChange={setData} /></div>","depois":"        <div className=\"grid gap-4 sm:grid-cols-3\"><Input label=\"Valor pago\" type=\"number\" min=\"0.01\" step=\"0.01\" value={valor} onChange={setValor} /><Input label={dataFim ? \"De (primeiro dia)\" : \"Data\"} type=\"date\" value={data} onChange={setData} /><Input label=\"Até (opcional)\" type=\"date\" value={dataFim} onChange={setDataFim} /></div>\n        {dataFim && dataFim > data ? <div className=\"rounded-2xl border border-sky-300/15 bg-sky-400/8 p-3 text-xs leading-5 text-sky-100\">O valor será dividido por igual entre os {Math.round((new Date(`${dataFim}T12:00:00`).getTime() - new Date(`${data}T12:00:00`).getTime()) / 86400000) + 1} dias do período (um lançamento por dia), para aparecer no dia certo nas telas de período.</div> : dataFim ? <div className=\"rounded-2xl border border-rose-300/15 bg-rose-400/8 p-3 text-xs leading-5 text-rose-100\">O &quot;Até&quot; precisa ser depois do primeiro dia.</div> : null}\n        {campanha.gastoAutomaticoDesde ? <div className=\"rounded-2xl border border-rose-300/15 bg-rose-400/8 p-3 text-xs leading-5 text-rose-100\">Esta campanha recebe o gasto do Google Ads sozinha desde {campanha.gastoAutomaticoDesde.split(\"-\").reverse().join(\"/\")}. Não lance à mão o gasto do Google desses dias, senão ele conta em dobro.</div> : null}"},{"nome":"ajuste 4","antes":"disabled={disabled || !descricao.trim() || Number(valor) <= 0 || !contaId} onClick={() => onSubmit({ descricao, valor: Number(valor), data, contaFinanceiraId: contaId ? Number(contaId) : null, observacoes })}","depois":"disabled={disabled || !descricao.trim() || Number(valor) <= 0 || !contaId || Boolean(dataFim && dataFim <= data)} onClick={() => onSubmit({ descricao, valor: Number(valor), data, dataFim: dataFim || null, contaFinanceiraId: contaId ? Number(contaId) : null, observacoes })}"},{"nome":"ajuste 5","antes":"                Conversões Google Ads\n              </Link>","depois":"                Conversões Google Ads\n              </Link>\n              <Link\n                href=\"/marketing/gasto-google-ads\"\n                className=\"inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 shadow-sm hover:border-violet-200 hover:bg-violet-50 hover:text-violet-800\"\n              >\n                Gasto Google Ads\n              </Link>"}]}]};
const raiz = process.cwd();
const aGravar = [];
let erros = 0;
let avisos = 0;

for (const [relativo, conteudo] of Object.entries(DATA.novosArquivos)) {
  const caminho = path.join(raiz, ...relativo.split("/"));
  const existente = fs.existsSync(caminho) ? fs.readFileSync(caminho, "utf8").replace(/\r\n/g, "\n") : null;
  if (existente === conteudo) {
    console.log("[pulou] " + relativo + " - ja existe igual");
  } else {
    aGravar.push({ caminho, conteudo, pasta: true });
    console.log((existente === null ? "[ok] criar " : "[ok] atualizar ") + relativo);
  }
}

for (const arq of DATA.arquivos) {
  const caminho = path.join(raiz, ...arq.arquivo.split("/"));
  if (!fs.existsSync(caminho)) {
    if (arq.obrigatorio) { console.log("[erro] arquivo nao encontrado: " + arq.arquivo + ". Rode na pasta do projeto."); erros++; }
    else { console.log("[aviso] arquivo nao encontrado, mantido: " + arq.arquivo); avisos++; }
    continue;
  }
  const bruto = fs.readFileSync(caminho, "utf8");
  const crlf = bruto.includes("\r\n");
  let texto = bruto.replace(/\r\n/g, "\n");
  let mudou = false;

  for (const p of arq.patches) {
    const ocorrencias = texto.split(p.antes).length - 1;
    if (p.modo === "remover") {
      // trecho a ser tirado: se ainda existe, tira; se nao existe, ja foi feito
      if (ocorrencias === 1) {
        texto = texto.replace(p.antes, () => p.depois);
        mudou = true;
        console.log("[ok] " + p.nome + " (" + arq.arquivo + ")");
      } else if (ocorrencias === 0) {
        console.log("[pulou] " + p.nome + " (" + arq.arquivo + ") - ja feito ou trecho diferente");
      } else {
        console.log("[aviso] " + p.nome + " (" + arq.arquivo + ") - aparece mais de uma vez, mantido");
        avisos++;
      }
      continue;
    }
    if (texto.includes(p.depois)) {
      console.log("[pulou] " + p.nome + " (" + arq.arquivo + ") - ja aplicado");
    } else if (ocorrencias === 1) {
      texto = texto.replace(p.antes, () => p.depois);
      mudou = true;
      console.log("[ok] " + p.nome + " (" + arq.arquivo + ")");
    } else {
      console.log("[erro] " + p.nome + " (" + arq.arquivo + ") - trecho nao encontrado");
      erros++;
    }
  }
  if (mudou) aGravar.push({ caminho, conteudo: crlf ? texto.replace(/\n/g, "\r\n") : texto });
}

if (erros > 0) {
  console.log("\nNada foi gravado: " + erros + " problema(s). Me mande esta tela.");
  process.exit(1);
}
for (const g of aGravar) {
  if (g.pasta) fs.mkdirSync(path.dirname(g.caminho), { recursive: true });
  fs.writeFileSync(g.caminho, g.conteudo, "utf8");
}
if (avisos > 0) console.log("\n" + avisos + " aviso(s): trechos opcionais que ficaram como estavam (nada quebra).");
console.log("\nConcluido.");
